<?php
namespace App\Http\Controllers; use App\Models\Product; use App\Models\Report; use App\Models\Role; use App\Services\NotificationService; use Illuminate\Http\Request;
class ProductReportController extends Controller { public function store(Request $r,Product $product){$data=$r->validate(['reason'=>['required','in:prohibited_product,misleading_information,fake_product,scam_suspicion,inappropriate_product_image,counterfeit_suspicion,incorrect_listing,other'],'description'=>['required','string','max:2000'],'evidence'=>['nullable','array','max:3'],'evidence.*'=>['image','mimes:jpeg,png,jpg,webp','max:2048']]);$existing=Report::where('target_type',Product::class)->where('target_id',$product->id)->where('reporter_id',$r->user()->id)->whereIn('status',['open','under_review'])->first();if($existing)return back()->with('error','You already submitted an open report for this product.');$report=Report::create(['report_number'=>Report::number(),'reporter_id'=>$r->user()->id,'target_type'=>Product::class,'target_id'=>$product->id,'reason'=>$data['reason'],'description'=>$data['description'],'priority'=>'normal','source'=>'user_report']);foreach($r->file('evidence',[]) as $file)$report->evidence()->create(['path'=>$file->store('report-evidence','public')]);foreach(Role::whereIn('slug',['admin','super_admin'])->with('users')->get() as $role)foreach($role->users as $user)NotificationService::send($user->id,'New product report',"{$product->name} was reported.",'report',$role->slug==='super_admin'?route('superadmin.reports.show',$report):route('admin.reports.show',$report));return back()->with('success','Report submitted. Our team will review it.');} }
